/// <summary>
/// CB453_BackOrders
/// </summary>
internal final class METCancelBackorderLinesService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// The process method for the back orders processing
    /// </summary>
    /// <param name = "_contract">The data contract object</param>
    public void processOperation(METCancelBackorderLinesContract _contract)
    { 
        int i = 0;
        boolean errorAllowSalesBackOrder = false;

        METNumDaysAfterDeliveryDate numDaysAfterDeliveryDate = _contract.parmNumDaysAfterDeliveryDate();
        
        [errorAllowSalesBackOrder, i] = this.cancelBackOrderLines(numDaysAfterDeliveryDate);

        str infoMessage = strFmt("@MET:CancelBackorderLinesServiceInfo", i);

        // if there was at least one error during 2 cancellations from above
        if (errorAllowSalesBackOrder)
        {
            // Throw error so that batch job status is updated to error
            throw error("@MET:CancelBackorderLinesServiceError" + METConstants::space + infoMessage);
        }

        info(infoMessage);
    }

    /// <summary>
    /// Cancel backorder lines
    /// </summary>
    /// <param name = "_numDaysAfterDeliveryDate">Number of days after delivery date</param>
    /// <returns>container with false if any errors; otherwise true and the number of sales line cancelled</returns>
    container cancelBackOrderLines(METNumDaysAfterDeliveryDate _numDaysAfterDeliveryDate)
    {
        Query query;
        QueryRun queryRun;
        int i = 0;
        SalesLine salesLine;
        boolean error = false;

        // Build the query
        query = this.buildQuery(_numDaysAfterDeliveryDate);
        
        queryRun = new QueryRun(query);

        // loop through all backorder lines
        while (queryRun.next())
        {
            // get salesLine to cancel
            salesLine = queryRun.get(tableNum(SalesLine));

            try
            {
                setPrefix(strFmt("@MET:CancelBackorderLinesServicePrefix", salesLine.SalesId, salesLine.LineNum, salesLine.InventTransId));
                
                // cancel the salesLine
                salesLine.metCancelSalesOrderLine();
                i++;
            }
            // If any errors continue to the next backorder line to cancel
            catch (Exception::Error)
            {
                error = true;
            }
        }

        return [error, i];
    }

    /// <summary>
    /// Build query to cancel backorder lines
    /// </summary>
    /// <param name = "_numDaysAfterDeliveryDate">Number of days after delivery date</param>
    /// <returns>Query object</returns>
    Query buildQuery(METNumDaysAfterDeliveryDate _numDaysAfterDeliveryDate)
    {
        QueryBuildDataSource qbdsSalesLine;
        
        Query query = new Query(queryStr(METCancelBackOrderLines));
        
        qbdsSalesLine = query.dataSourceTable(tableNum(SalesLine));

        // add a filter on the requested ship date <= today - _numDaysAfterDeliveryDate
        QueryBuildRange qbrNumDaysAfterDeliveryDate = qbdsSalesLine.findRange(fieldnum(SalesLine, ShippingDateRequested));
        qbrNumDaysAfterDeliveryDate.value(SysQueryRangeUtil::metLessThanEqualDate(SysQueryRangeUtil::METDay(-_numDaysAfterDeliveryDate)));

        return query;
    }
